CREATE DATABASE IF NOT EXISTS library_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE library_management;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(120) NOT NULL,role ENUM('admin','librarian') DEFAULT 'librarian',status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE authors(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL);
CREATE TABLE books(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,accession_no VARCHAR(50) UNIQUE NOT NULL,isbn VARCHAR(30),title VARCHAR(255) NOT NULL,publisher VARCHAR(150),edition VARCHAR(50),publication_year YEAR NULL,category_id INT UNSIGNED NULL,author_id INT UNSIGNED NULL,language VARCHAR(50) DEFAULT 'English',price DECIMAL(10,2) DEFAULT 0,total_copies INT UNSIGNED DEFAULT 1,available_copies INT UNSIGNED DEFAULT 1,shelf_no VARCHAR(50),status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,FOREIGN KEY(author_id) REFERENCES authors(id) ON DELETE SET NULL);
CREATE TABLE members(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,member_code VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,member_type ENUM('student','faculty','staff','other') DEFAULT 'student',enrollment_no VARCHAR(80),department VARCHAR(120),mobile VARCHAR(20),email VARCHAR(150),address TEXT,registered_on DATE NOT NULL,status ENUM('active','suspended','expired') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE loans(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,book_id INT UNSIGNED NOT NULL,member_id INT UNSIGNED NOT NULL,issued_by INT UNSIGNED NOT NULL,issue_date DATE NOT NULL,due_date DATE NOT NULL,return_date DATE NULL,fine_amount DECIMAL(10,2) DEFAULT 0,status ENUM('issued','returned','lost') DEFAULT 'issued',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(book_id) REFERENCES books(id),FOREIGN KEY(member_id) REFERENCES members(id),FOREIGN KEY(issued_by) REFERENCES users(id));
CREATE TABLE settings(setting_key VARCHAR(50) PRIMARY KEY,setting_value VARCHAR(255) NOT NULL);
INSERT INTO settings VALUES ('loan_days','14'),('fine_per_day','2'),('max_books_student','3'),('max_books_faculty','5'),('max_books_staff','3') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
INSERT INTO categories(name) VALUES('Computer Science'),('Management'),('Mathematics'),('Electronics') ON DUPLICATE KEY UPDATE name=VALUES(name);